import numpy as np

# Define the sigmoid function
def sigmoid(x):
    return 1 / (1 + np.exp(-x))

# Define the ReLU function
def relu(x):
    return np.maximum(0, x)

import numpy as np

# Define a simple neural network
weights = np.array([0.1, 0.2, 0.3])
input_data = np.array([1, 2, 3])

# Forward propagation
def forward_propagate(input_data, weights):
    return np.dot(input_data, weights)

# Backpropagation
def backpropagate(error, input_data, weights):
    return error * input_data

import numpy as np
# Define a simple loss function (MSE)
def mse_loss(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)
